// =======================================
// CustomerBookingForm.jsx
// Customer-facing Booking Request Page
//   - Guest fills stay dates + guest details (adults male/female, child)
//   - NO room selection/allotment here (that's done later by Admin
//     from the Manage Bookings page)
//   - After submit -> shows "Booked" with a note that booking will
//     be confirmed only after payment
//   - Cancellation policy disclaimer always visible
// Backend: Google Apps Script + Google Sheet
// =======================================

import React, { useState, useRef, useEffect } from "react";

// =======================================
// dataUrlToBlob - synchronous canvas-dataURL -> Blob conversion.
// canvas.toBlob() is async, and on some mobile browsers (esp. iOS
// Safari) the small delay is enough to lose "user activation" on
// the click, which silently breaks navigator.share()/window.open().
// canvas.toDataURL() is synchronous, so converting it this way keeps
// the whole share flow inside the original click's activation window.
// =======================================

const dataUrlToBlob = (dataUrl) => {
  const [header, base64] = dataUrl.split(",");
  const mimeMatch = header.match(/:(.*?);/);
  const mime = mimeMatch ? mimeMatch[1] : "image/png";
  const binary = atob(base64);
  const len = binary.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new Blob([bytes], { type: mime });
};

// Standard check-in / check-out times shown alongside the dates
const CHECKIN_TIME_LABEL = "12:00 AM";
const CHECKOUT_TIME_LABEL = "11:00 AM";

// Trust's donation QR code (static image) - same QR used on the
// admin RoomBookingForm confirmation share. PASTE YOUR ORIGINAL
// base64 string here (copy it from RoomBookingForm.jsx's
// QR_CODE_IMAGE_PATH so both pages show the exact same QR).
const QR_CODE_IMAGE_PATH = "data:image/jpeg;base64,";

// =======================================
// CHANGE THIS to your deployed Apps Script Web App URL
// (same backend as the admin RoomBookingForm)
// =======================================

const API_URL =
  "https://script.google.com/macros/s/AKfycbzxOeJWJ5K07N2uFILqe7l1l2VIesucTFoFJKP9QECxWPuYHNN250RyDC-238L1RkeOGA/exec";

const CustomerBookingForm = () => {

  // ---- stay details ----
  const [checkIn, setCheckIn] = useState("");
  const [checkOut, setCheckOut] = useState("");

  // ---- guest details ----
  const [name, setName] = useState("");
  const [gender, setGender] = useState(""); // "Male" | "Female"
  const [mobile, setMobile] = useState("");
  const [adultMale, setAdultMale] = useState("");
  const [adultFemale, setAdultFemale] = useState("");
  const [child, setChild] = useState("");

  const [submitting, setSubmitting] = useState(false);
  const [bookingResult, setBookingResult] = useState(null);
  const [errorModal, setErrorModal] = useState("");

  // ---- check booking status (customer-facing, read-only) ----
  const [statusBookingId, setStatusBookingId] = useState("");
  const [statusLoading, setStatusLoading] = useState(false);
  const [statusBookings, setStatusBookings] = useState([]);
  const [statusSearched, setStatusSearched] = useState(false);

  // ---- canvas used to build the booking-confirmation share image ----
  const bookingCanvasRef = useRef(null);
  const [confirmationSharing, setConfirmationSharing] = useState(false);

  // Preload the donation QR once on mount, so by the time the guest
  // taps "Share", the image is already decoded and the whole canvas
  // draw + share can run synchronously inside the click (see note on
  // dataUrlToBlob above for why that matters on mobile).
  const qrImageRef = useRef(null); // holds the loaded <img>, or null if it failed
  const qrImageReadyRef = useRef(false); // true once load/error has settled

  useEffect(() => {

    const img = new Image();

    img.onload = () => {
      qrImageRef.current = img;
      qrImageReadyRef.current = true;
    };

    img.onerror = (err) => {
      console.log("QR image failed to load:", QR_CODE_IMAGE_PATH, err);
      qrImageRef.current = null;
      qrImageReadyRef.current = true;
    };

    img.src = QR_CODE_IMAGE_PATH;

  }, []);



  // =======================================
  // RESET FORM (after a successful booking request)
  // =======================================

  const resetForm = () => {
    setCheckIn("");
    setCheckOut("");
    setName("");
    setGender("");
    setMobile("");
    setAdultMale("");
    setAdultFemale("");
    setChild("");
  };



  // =======================================
  // SUBMIT BOOKING REQUEST (no room number - admin allots later)
  // =======================================

  const submitBookingRequest = async () => {

    if (!checkIn || !checkOut) {
      setErrorModal("Check-in और Check-out date चुनें");
      return;
    }

    if (new Date(checkOut) <= new Date(checkIn)) {
      setErrorModal("Check-out date, Check-in date के बाद की होनी चाहिए");
      return;
    }

    if (!name || !mobile || !gender) {
      setErrorModal("Name, Gender और Mobile Number भरें");
      return;
    }

    if (mobile.length !== 10) {
      setErrorModal("सही 10 digit Mobile Number डालें");
      return;
    }

    const totalGuests =
      (Number(adultMale) || 0) +
      (Number(adultFemale) || 0) +
      (Number(child) || 0);

    if (totalGuests <= 0) {
      setErrorModal("कम से कम 1 Guest की details भरें");
      return;
    }

    setSubmitting(true);
    setBookingResult(null);

    try {

      const payload = {
        // Reusing the same "createBooking" action as the admin form.
        // roomNumber is sent as "0" (placeholder) since the customer
        // does not choose/get allotted a real room here - Admin will
        // manually change "0" to the actual room number later (in
        // the Manage Bookings sheet/page).
        action: "createBooking",
        name,
        gender,
        mobile,
        adultMale: adultMale || 0,
        adultFemale: adultFemale || 0,
        child: child || 0,
        extraBedding: 0,
        checkIn,
        checkOut,
        aadhar4: "",
        bookedBy: "Customer Online Booking",
        roomNumber: "0",
      };

      const response = await fetch(API_URL, {
        method: "POST",
        body: JSON.stringify(payload),
      });

      const data = await response.json();

      if (data.success) {

        setBookingResult({
          ...data,
          name,
          mobile,
          checkIn,
          checkOut,
        });

        resetForm();

      } else {

        setErrorModal(data.message || "Booking request failed");
      }

    } catch (err) {

      console.log(err);
      setErrorModal("Something went wrong");

    } finally {

      setSubmitting(false);
    }
  };



  // =======================================
  // CREATE BOOKING CONFIRMATION IMAGE (canvas)
  // Same style as the admin RoomBookingForm share, but no room
  // number (not allotted yet) and a payment-pending note instead.
  // =======================================

  const createBookingConfirmationImage = (callback) => {

    const canvas =
      bookingCanvasRef.current || document.createElement("canvas");

    const ctx = canvas.getContext("2d");

    const width = 640;

    const drawCard = (qrImg) => {

      // fixed layout up to the QR block
      const headerBottom = 200 + 4 * 42; // 4 detail lines starting at y=200
      const afterDetailsY = headerBottom + 10;
      const noteY = afterDetailsY + 35;
      const qrLabelY = noteY + 45;
      const qrTop = qrLabelY + 20;

      // QR sizing - fit a generous width, keep the image's own
      // aspect ratio so its internal text/logo isn't squashed
      const qrDisplayWidth = 360;
      let qrDisplayHeight = 0;

      if (qrImg) {
        const ratio = qrImg.naturalHeight / qrImg.naturalWidth;
        qrDisplayHeight = Math.round(qrDisplayWidth * ratio);
      }

      const footerGap = 30;
      const footerY = qrImg
        ? qrTop + qrDisplayHeight + footerGap
        : qrTop + footerGap;

      const height = footerY + 30; // bottom padding under footer

      canvas.width = width;
      canvas.height = height;

      // background
      ctx.fillStyle = "#fff7ed";
      ctx.fillRect(0, 0, width, height);

      // border
      ctx.strokeStyle = "#ea580c";
      ctx.lineWidth = 6;
      ctx.strokeRect(10, 10, width - 20, height - 20);

      // header
      ctx.fillStyle = "#ea580c";
      ctx.textAlign = "center";
      ctx.font = "bold 26px Arial";
      ctx.fillText("Room Booking Request Received", width / 2, 55);

      ctx.fillStyle = "#111827";
      ctx.font = "bold 20px Arial";
      ctx.fillText(
        "Shree Maruti Nandan Dham, Mehandipur Balaji",
        width / 2,
        88
      );

      ctx.strokeStyle = "#fed7aa";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(40, 108);
      ctx.lineTo(width - 40, 108);
      ctx.stroke();

      // details
      ctx.textAlign = "left";
      ctx.font = "22px Arial";
      ctx.fillStyle = "#1f2937";

      const lines = [
        `Name: ${bookingResult.name}`,
        `Mobile: ${bookingResult.mobile}`,
        `Check-in: ${bookingResult.checkIn} ${CHECKIN_TIME_LABEL}`,
        `Check-out: ${bookingResult.checkOut} ${CHECKOUT_TIME_LABEL}`,
      ];

      let y = 200;

      lines.forEach((line) => {
        ctx.fillText(line, 60, y);
        y += 42;
      });

      if (bookingResult.bookingId) {
        ctx.font = "18px Arial";
        ctx.fillStyle = "#6b7280";
        ctx.fillText(`Booking ID: ${bookingResult.bookingId}`, 60, y);
      }

      ctx.strokeStyle = "#fed7aa";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(40, afterDetailsY);
      ctx.lineTo(width - 40, afterDetailsY);
      ctx.stroke();

      // payment-pending note
      ctx.textAlign = "center";
      ctx.fillStyle = "#c2410c";
      ctx.font = "bold 18px Arial";
      ctx.fillText(
        "Booking confirm payment के बाद होगी",
        width / 2,
        noteY
      );

      // QR label
      ctx.fillStyle = "#16a34a";
      ctx.font = "bold 16px Arial";
      ctx.fillText("Payment के लिए QR स्कैन करें", width / 2, qrLabelY);

      // QR image (Trust's donation QR - same static image every time),
      // drawn at its own aspect ratio so it isn't stretched/squashed
      if (qrImg) {
        const qrX = (width - qrDisplayWidth) / 2;
        ctx.drawImage(qrImg, qrX, qrTop, qrDisplayWidth, qrDisplayHeight);
      }

      // footer - placed dynamically below the QR, never overlapping it
      ctx.textAlign = "center";
      ctx.fillStyle = "#2563eb";
      ctx.font = "16px Arial";
      ctx.fillText("Shri Sankat Mochan Balaji Mandal", width / 2, footerY);

      callback(canvas);
    };

    // if the QR was already preloaded on mount, draw synchronously -
    // this is the path used by Share (keeps user-activation intact)
    if (qrImageReadyRef.current) {
      drawCard(qrImageRef.current);
      return;
    }

    // fallback (e.g. Share tapped before the preload finished) - load
    // it now, async, same as before
    const qrImg = new Image();

    qrImg.onload = () => {
      qrImageRef.current = qrImg;
      qrImageReadyRef.current = true;
      drawCard(qrImg);
    };

    qrImg.onerror = (err) => {
      console.log("QR image failed to load:", QR_CODE_IMAGE_PATH, err);
      qrImageRef.current = null;
      qrImageReadyRef.current = true;
      drawCard(null);
    };

    qrImg.src = QR_CODE_IMAGE_PATH;
  };



  // =======================================
  // SHARE BOOKING CONFIRMATION ON WHATSAPP
  // =======================================

  const shareBookingOnWhatsapp = () => {

    if (!bookingResult) return;

    setConfirmationSharing(true);

    const shareText =
      `🙏 Room Booking Request Received\n` +
      `Name: ${bookingResult.name}\n` +
      `Check-in: ${bookingResult.checkIn} ${CHECKIN_TIME_LABEL}\n` +
      `Check-out: ${bookingResult.checkOut} ${CHECKOUT_TIME_LABEL}\n` +
      (bookingResult.bookingId
        ? `Booking ID: ${bookingResult.bookingId}\n`
        : "") +
      `Booking confirm payment के बाद होगी`;

    const isMobile = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);

    const finishShare = (canvas) => {

      try {

        // toDataURL is synchronous (unlike toBlob), so this whole
        // function runs inside the same tick as the click - keeps
        // "user activation" alive for navigator.share()/window.open()
        // on strict mobile browsers (esp. iOS Safari).
        const dataUrl = canvas.toDataURL("image/png");
        const blob = dataUrlToBlob(dataUrl);

        const file = new File(
          [blob],
          "booking-request.png",
          { type: "image/png" }
        );

        if (
          isMobile &&
          navigator.canShare &&
          navigator.canShare({ files: [file] })
        ) {

          navigator
            .share({
              title: "Room Booking Request Received",
              text: shareText,
              files: [file],
            })
            .catch((err) => {

              if (err && err.name === "AbortError") {
                console.log("Share cancelled by user");
              } else {
                console.log(err);
              }
            })
            .finally(() => setConfirmationSharing(false));

          return;
        }

        // download the image (works on both mobile and desktop)
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = "booking-request.png";
        link.click();
        URL.revokeObjectURL(url);

        // open WhatsApp (Web on desktop, app on mobile) with the text
        window.open(
          `https://wa.me/?text=${encodeURIComponent(shareText)}`,
          "_blank"
        );

        setConfirmationSharing(false);

      } catch (err) {

        console.log(err);
        setConfirmationSharing(false);
      }
    };

    try {

      createBookingConfirmationImage(finishShare);

    } catch (err) {

      console.log(err);
      setConfirmationSharing(false);
    }
  };



  // =======================================
  // CHECK YOUR BOOKING STATUS (read-only, no actions)
  // Searches by Booking ID - assumes backend action
  // "checkBookingStatus" accepts ?bookingId=BKxxxxxxxxxx and returns
  // { success, bookings: [{ name, mobile, checkIn, checkOut,
  // roomNumber, status, bookingId }, ...] }.
  // ⚠️ CONFIRM this action name / param matches your Apps Script -
  // adjust the URL below if yours is named differently.
  // =======================================

  const checkBookingStatus = async () => {

    if (!statusBookingId.trim()) {
      setErrorModal("Booking ID डालें");
      return;
    }

    setStatusLoading(true);
    setStatusSearched(false);

    try {

      const response = await fetch(
        `${API_URL}?action=checkBookingStatus&bookingId=${encodeURIComponent(
          statusBookingId.trim()
        )}`
      );

      const data = await response.json();

      if (data.success) {

        setStatusBookings(data.bookings || []);
        setStatusSearched(true);

      } else {

        setErrorModal(data.message || "Booking status नहीं मिल पाया");
      }

    } catch (err) {

      console.log(err);
      setErrorModal("Something went wrong");

    } finally {

      setStatusLoading(false);
    }
  };



  return (

    <div className="min-h-screen bg-orange-50 flex justify-center px-3 py-6 sm:px-4 sm:py-10">

      <div className="w-full max-w-2xl bg-white rounded-2xl shadow-lg p-4 sm:p-6">

        <h1 className="text-xl sm:text-3xl font-bold text-center text-orange-600 mb-1">
          Room Booking Request
        </h1>

        <p className="text-center text-gray-500 text-sm mb-8">
          Shree Maruti Nandan Dham, Mehandipur Balaji
        </p>



        {!bookingResult && (

          <>

            {/* ======================================= */}
            {/* STAY DATES */}
            {/* ======================================= */}

            <div className="bg-orange-50 border rounded-2xl p-4 sm:p-6 mb-6">

              <h2 className="text-lg sm:text-xl font-bold text-orange-600 mb-5">
                Stay Dates
              </h2>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

                <div>
                  <label className="text-sm font-medium text-gray-700">
                    Check-in Date
                  </label>
                  <input
                    type="date"
                    value={checkIn}
                    onChange={(e) => setCheckIn(e.target.value)}
                    className="border rounded-md px-3 py-2 w-full mt-1"
                  />
                </div>

                <div>
                  <label className="text-sm font-medium text-gray-700">
                    Check-out Date
                  </label>
                  <input
                    type="date"
                    value={checkOut}
                    onChange={(e) => setCheckOut(e.target.value)}
                    className="border rounded-md px-3 py-2 w-full mt-1"
                  />
                </div>

              </div>

            </div>



            {/* ======================================= */}
            {/* GUEST DETAILS */}
            {/* ======================================= */}

            <div className="bg-orange-50 border rounded-2xl p-4 sm:p-6 mb-6">

              <h2 className="text-lg sm:text-xl font-bold text-orange-600 mb-5">
                Guest Details
              </h2>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

                <div>
                  <label className="text-sm font-medium text-gray-700">
                    Name
                  </label>
                  <input
                    type="text"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="border rounded-md px-3 py-2 w-full mt-1"
                    placeholder="Guest Name"
                  />
                </div>

                <div>
                  <label className="text-sm font-medium text-gray-700">
                    Mobile Number
                  </label>
                  <input
                    type="tel"
                    maxLength={10}
                    value={mobile}
                    onChange={(e) =>
                      setMobile(e.target.value.replace(/\D/g, ""))
                    }
                    className="border rounded-md px-3 py-2 w-full mt-1"
                    placeholder="10 digit mobile"
                  />
                </div>

                <div>
                  <label className="text-sm font-medium text-gray-700 block mb-2">
                    Gender
                  </label>

                  <div className="flex gap-5">

                    <label className="flex items-center gap-2 text-sm">
                      <input
                        type="checkbox"
                        checked={gender === "Male"}
                        onChange={() =>
                          setGender(gender === "Male" ? "" : "Male")
                        }
                        className="w-5 h-5 accent-orange-600"
                      />
                      Male
                    </label>

                    <label className="flex items-center gap-2 text-sm">
                      <input
                        type="checkbox"
                        checked={gender === "Female"}
                        onChange={() =>
                          setGender(gender === "Female" ? "" : "Female")
                        }
                        className="w-5 h-5 accent-orange-600"
                      />
                      Female
                    </label>

                  </div>
                </div>

                <div>
                  <label className="text-sm font-medium text-gray-700">
                    Adult - Male
                  </label>
                  <input
                    type="number"
                    min="0"
                    value={adultMale}
                    onChange={(e) => setAdultMale(e.target.value)}
                    className="border rounded-md px-3 py-2 w-full mt-1"
                    placeholder="0"
                  />
                </div>

                <div>
                  <label className="text-sm font-medium text-gray-700">
                    Adult - Female
                  </label>
                  <input
                    type="number"
                    min="0"
                    value={adultFemale}
                    onChange={(e) => setAdultFemale(e.target.value)}
                    className="border rounded-md px-3 py-2 w-full mt-1"
                    placeholder="0"
                  />
                </div>

                <div>
                  <label className="text-sm font-medium text-gray-700">
                    Child
                  </label>
                  <input
                    type="number"
                    min="0"
                    value={child}
                    onChange={(e) => setChild(e.target.value)}
                    className="border rounded-md px-3 py-2 w-full mt-1"
                    placeholder="0"
                  />
                </div>

              </div>

            </div>

            <button
              onClick={submitBookingRequest}
              disabled={submitting}
              className="w-full bg-orange-600 hover:bg-orange-700 disabled:opacity-60 text-white px-8 py-3 rounded-md font-semibold text-lg"
            >
              {submitting ? "Booking हो रही है..." : "Book Now"}
            </button>

          </>

        )}



        {/* ======================================= */}
        {/* BOOKING SUBMITTED RESULT */}
        {/* ======================================= */}

        {bookingResult && (

          <div className="mb-8 bg-green-50 border border-green-300 rounded-xl p-5 text-center">

            <p className="text-green-700 font-bold text-xl">
              Booked ✅
            </p>

            <p className="text-gray-700 mt-2">
              Name: <span className="font-semibold">{bookingResult.name}</span>
            </p>

            <p className="text-gray-700">
              Check-in: {bookingResult.checkIn} {CHECKIN_TIME_LABEL}
            </p>

            <p className="text-gray-700">
              Check-out: {bookingResult.checkOut} {CHECKOUT_TIME_LABEL}
            </p>

            {bookingResult.bookingId && (
              <p className="text-gray-500 text-sm mt-1">
                Booking ID: {bookingResult.bookingId}
              </p>
            )}

            <p className="text-orange-700 font-medium text-sm mt-4">
              Booking confirm payment के बाद होगी।
            </p>

            <div className="mt-5 bg-white border border-green-300 rounded-xl p-4 inline-block">

              <p className="text-green-700 font-bold text-sm mb-3">
                Payment के लिए QR स्कैन करें
              </p>

              <img
                src={QR_CODE_IMAGE_PATH}
                alt="Payment QR Code"
                className="w-48 h-auto mx-auto rounded-md"
              />

            </div>

            <div>
              <button
                onClick={shareBookingOnWhatsapp}
                disabled={confirmationSharing}
                className="mt-5 w-full sm:w-auto bg-green-600 hover:bg-green-700 disabled:opacity-60 text-white px-6 py-2 rounded-md font-semibold"
              >
                {confirmationSharing
                  ? "तैयार हो रहा है..."
                  : "📤 Share on WhatsApp"}
              </button>
            </div>

            <canvas
              ref={bookingCanvasRef}
              style={{ display: "none" }}
            />

            <button
              onClick={() => setBookingResult(null)}
              className="mt-5 block mx-auto text-sm text-gray-500 underline"
            >
              Book another room
            </button>

          </div>

        )}



        {/* ======================================= */}
        {/* CANCELLATION POLICY DISCLAIMER */}
        {/* ======================================= */}

        <div className="mt-4 bg-yellow-50 border border-yellow-300 rounded-xl p-4 sm:p-5">

          <h3 className="text-sm sm:text-base font-bold text-yellow-800 mb-2">
            Cancellation Policy
          </h3>

          <ul className="text-xs sm:text-sm text-gray-700 space-y-1 list-disc list-inside">

            <li>
              Check-in से <span className="font-semibold">48 hours पहले</span>{" "}
              cancel करने पर <span className="font-semibold">full refund</span>{" "}
              मिलेगा।
            </li>

            <li>
              Check-in से{" "}
              <span className="font-semibold">48 से 24 hours</span> के बीच
              cancel करने पर{" "}
              <span className="font-semibold">50% refund</span> मिलेगा।
            </li>

            <li>
              Check-in से{" "}
              <span className="font-semibold">24 hours के अंदर</span> cancel
              करने पर <span className="font-semibold">कोई refund नहीं</span>{" "}
              मिलेगा।
            </li>

          </ul>

        </div>



        {/* ======================================= */}
        {/* CHECK YOUR BOOKING STATUS (read-only) */}
        {/* ======================================= */}

        <div className="mt-6 bg-orange-50 border rounded-2xl p-4 sm:p-6">

          <h2 className="text-lg sm:text-xl font-bold text-orange-600 mb-5">
            Check Your Booking Status
          </h2>

          <div className="flex flex-col md:flex-row gap-4">

            <input
              type="text"
              value={statusBookingId}
              onChange={(e) => setStatusBookingId(e.target.value)}
              className="border rounded-md px-4 py-2 w-full"
              placeholder="अपना Booking ID डालें (जैसे BK1234567890)"
            />

            <button
              onClick={checkBookingStatus}
              disabled={statusLoading}
              className="bg-orange-600 hover:bg-orange-700 disabled:opacity-60 text-white px-6 py-2 rounded-md whitespace-nowrap"
            >
              {statusLoading ? "Checking..." : "Check Status"}
            </button>

          </div>

          {statusSearched && (

            <div className="overflow-auto rounded-xl border bg-white mt-5">

              <table className="w-full border-collapse text-xs sm:text-sm">

                <thead>
                  <tr className="bg-orange-100">
                    <th className="border p-2">Name</th>
                    <th className="border p-2">Check-in</th>
                    <th className="border p-2">Check-out</th>
                    <th className="border p-2">Room</th>
                    <th className="border p-2">Status</th>
                  </tr>
                </thead>

                <tbody>

                  {statusBookings.length > 0 ? (

                    statusBookings.map((b, idx) => {

                      const isUnassigned =
                        !b.roomNumber || String(b.roomNumber) === "0";

                      // "status" is your internal Active/Cancelled/
                      // Completed value from the sheet - shown as-is
                      // when it's Cancelled/Completed, otherwise
                      // derived from whether a room is assigned yet.
                      let displayStatus = "Booked";
                      let statusColor = "bg-green-100 text-green-700";

                      if (b.status === "Cancelled") {
                        displayStatus = "Cancelled";
                        statusColor = "bg-red-100 text-red-700";
                      } else if (b.status === "Completed") {
                        displayStatus = "Completed";
                        statusColor = "bg-gray-100 text-gray-600";
                      } else if (isUnassigned) {
                        displayStatus = "Not Confirmed";
                        statusColor = "bg-orange-100 text-orange-700";
                      }

                      return (

                        <tr key={idx} className="hover:bg-orange-50">

                          <td className="border p-2">{b.name}</td>

                          <td className="border p-2">
                            {String(b.checkIn).split("T")[0]}
                          </td>

                          <td className="border p-2">
                            {String(b.checkOut).split("T")[0]}
                          </td>

                          <td className="border p-2 font-semibold">
                            {isUnassigned ? (
                              <span className="text-orange-600 text-xs font-medium">
                                Unassigned
                              </span>
                            ) : (
                              b.roomNumber
                            )}
                          </td>

                          <td className="border p-2">
                            <span
                              className={`px-2 py-1 rounded text-xs font-medium ${statusColor}`}
                            >
                              {displayStatus}
                            </span>
                          </td>

                        </tr>

                      );

                    })

                  ) : (

                    <tr>
                      <td colSpan="5" className="text-center p-5">
                        इस Booking ID पर कोई Booking नहीं मिली
                      </td>
                    </tr>

                  )}

                </tbody>

              </table>

            </div>

          )}

        </div>

      </div>



      {/* ======================================= */}
      {/* ERROR MODAL (replaces browser alert()) */}
      {/* ======================================= */}

      {errorModal && (

        <div className="fixed inset-0 bg-black/50 flex items-center justify-center px-4 z-50">

          <div className="bg-white rounded-2xl p-5 sm:p-6 w-full max-w-sm text-center">

            <div className="text-4xl mb-2">⚠️</div>

            <p className="text-gray-800 font-medium mb-5">
              {errorModal}
            </p>

            <button
              onClick={() => setErrorModal("")}
              className="w-full bg-orange-600 hover:bg-orange-700 text-white px-6 py-2.5 rounded-md font-semibold"
            >
              ठीक है
            </button>

          </div>

        </div>

      )}

    </div>
  );
};

export default CustomerBookingForm;